import "./dom.ts";

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { act, createElement } from "react";
import { createRoot } from "react-dom/client";

import { Registry } from "../src/App.tsx";
import { AppErrorBoundary } from "../src/ErrorBoundary.tsx";
import type { Job } from "../src/types.ts";
import { container } from "./dom.ts";

// Real JobStore payloads for every factory stage, including a DEV repair round
// (generated by backend/tests/test_factory_stage_shapes.py).
const stages = JSON.parse(readFileSync(new URL("./fixtures/factory-stages.json", import.meta.url), "utf8")) as Job[];
const RECOVERY_SCREEN = "temporary display error";
const styles = readFileSync(new URL("../src/styles.css", import.meta.url), "utf8");

function mount() {
  const root = createRoot(container());
  const errors: unknown[] = [];
  const original = console.error;
  console.error = (...args: unknown[]) => { errors.push(args[0]); };
  const render = (jobs: Job[], selectedJob?: string) => act(() => {
    root.render(createElement(AppErrorBoundary, null, createElement(Registry, {
      adapters: [], jobs, selectedJob, setSelectedJob: () => undefined,
      onTest: () => undefined, onRetry: async () => undefined,
    })));
  });
  const text = () => document.body.textContent || "";
  const unmount = () => { act(() => root.unmount()); console.error = original; document.body.innerHTML = ""; };
  return { render, text, unmount, errors };
}

test("every factory stage renders while the live view polls through a full run", async () => {
  const view = mount();
  try {
    for (const job of stages) {
      await view.render([job], job.job_id);
      assert.ok(!view.text().includes(RECOVERY_SCREEN), `blank live view at ${job.status} (round ${job.dataset_round})`);
    }
  } finally {
    view.unmount();
  }
});

test("switching to a job with fewer agent outputs keeps the live view up", async () => {
  const finished = { ...stages[stages.length - 1], job_id: "job-finished" };
  const early = { ...stages.find((job) => job.status === "integrating")!, job_id: "job-early" };
  assert.ok(finished.agent_outputs!.length > early.agent_outputs!.length + 1);
  const view = mount();
  try {
    await view.render([finished, early], finished.job_id);
    await view.render([finished, early], early.job_id);
    assert.ok(!view.text().includes(RECOVERY_SCREEN), "the recovery screen replaced the live view");
    assert.ok(view.text().includes(early.agent_outputs!.at(-1)!.summary), "shows the selected job's latest output");
  } finally {
    view.unmount();
  }
});

test("factory shows model ownership and a Sentry-informed retraining decision", async () => {
  const view = mount();
  try {
    const finished = stages[stages.length - 1];
    await view.render([finished], finished.job_id);
    assert.ok(view.text().includes("Skill architectKimi K3"));
    assert.ok(view.text().includes("Sentry feedback → retraining decision"));
    assert.ok(view.text().includes("No retraining needed"));
  } finally {
    view.unmount();
  }
});

test("completed factory status cannot inherit the absolute adapter badge layout", () => {
  assert.doesNotMatch(styles, /(?:^|\n)\.ready\s*,/);
  assert.match(styles, /\.adapter-card\s*>\s*\.ready/);
  assert.match(styles, /\.factory-panel\s*\{[^}]*position:\s*relative/);
});
